// Prepare URLs with metadata
const client = $('Get Client').first().json;
const run = $('Create Run').first().json;

const validGenres = [
  'Office Equipment & Technology', 'Food & Drink', 'Telecommunications & Internet',
  'Healthcare', 'Education', 'Tobacco & E-cigarettes', 'Charity & Nonprofit',
  'Fashion', 'Retail', 'Professional & Business Services', 'Property & Construction',
  'Agencies', 'Entertainment', 'Transportation & Logistics', 'Consumer Electronics',
  'Travel & Tourism', 'Financial', 'Utilities & Energy', 'Leisure & Hospitality',
  'Media & Publishing', 'Government & Public Sector', 'Cosmetics & Personal Care',
  'Home & Garden', 'Automotive', 'Manufacturing & Industrial', 'Household Consumer Goods'
];

const results = [];
for (const item of $input.all()) {
  const url = (item.json.URL || '').trim();
  const genre = (item.json.Genre || '').trim();

  if (!url || !genre || !validGenres.includes(genre)) continue;

  results.push({
    json: {
      homepage_url: url,
      genre: genre,
      client_id: client.id,
      run_id: run.id,
      client_name: client.name,
      recipients: client.recipients
    }
  });
}

return results.length > 0 ? results : [{ json: { error: 'No valid URLs' } }];

// Extract articles from homepage - SIMPLE VERSION
const items = $input.all();
const allArticles = [];

for (const item of items) {
  const homepage_url = item.json.homepage_url || '';
  const genre = item.json.genre || '';
  const client_id = item.json.client_id || '';
  const run_id = item.json.run_id || '';
  const recipients = item.json.recipients || [];

  let html = item.json.data || item.json.body || '';
  if (typeof html !== 'string') html = '';

  // Limit HTML size
  if (html.length > 300000) html = html.substring(0, 300000);

  let baseUrl;
  try {
    baseUrl = new URL(homepage_url).origin;
  } catch (e) {
    continue;
  }

  // Extract links
  const linkPattern = /href=["']([^"']{10,150})["']/gi;
  const found = [];
  let match;
  let count = 0;

  while ((match = linkPattern.exec(html)) !== null && count < 200) {
    count++;
    let href = match[1];

    // Skip obvious non-articles
    if (href.startsWith('#') || href.startsWith('javascript:') || href.startsWith('mailto:')) continue;
    if (/\.(css|js|png|jpg|gif|svg|ico|pdf|xml)$/i.test(href)) continue;
    if (/(\/tag\/|\/category\/|\/author\/|\/search|\/login|\/subscribe)/i.test(href)) continue;
    if (/(facebook|twitter|linkedin|instagram|youtube)\.com/i.test(href)) continue;

    // Resolve relative URLs
    if (href.startsWith('/')) {
      href = baseUrl + href;
    } else if (!href.startsWith('http')) {
      continue;
    }

    // Must be same domain
    try {
      if (new URL(href).hostname.replace('www.', '') !== new URL(baseUrl).hostname.replace('www.', '')) continue;
    } catch (e) { continue; }

    // Skip if it's just the homepage
    if (href.replace(/\/$/, '') === baseUrl.replace(/\/$/, '')) continue;

    found.push(href);
  }

  // Dedupe and limit
  const unique = [...new Set(found)].slice(0, 5);

  for (const url of unique) {
    allArticles.push({
      json: {
        article_url: url,
        genre: genre,
        client_id: client_id,
        run_id: run_id,
        recipients: recipients,
        source_homepage: homepage_url
      }
    });
  }
}

if (allArticles.length === 0) {
  return [{ json: { error: true, reason: 'No articles discovered' } }];
}

return allArticles.slice(0, 15); // Max 15 articles total

// Extract article content - SIMPLE VERSION
const items = $input.all();
const articles = [];

for (const item of items) {
  const articleUrl = item.json.article_url || '';
  const genre = item.json.genre || '';
  const clientId = item.json.client_id || '';
  const runId = item.json.run_id || '';
  const recipients = item.json.recipients || [];
  const sourceHomepage = item.json.source_homepage || '';

  let html = item.json.data || item.json.body || '';
  if (typeof html !== 'string' || html.length < 500) continue;
  if (html.length > 200000) html = html.substring(0, 200000);

  // Extract title
  let title = '';
  const ogTitle = html.match(/property=["']og:title["'][^>]*content=["']([^"']+)["']/i) ||
                  html.match(/content=["']([^"']+)["'][^>]*property=["']og:title["']/i);
  if (ogTitle) title = ogTitle[1];
  if (!title) {
    const titleTag = html.match(/<title[^>]*>([^<]+)<\/title>/i);
    if (titleTag) title = titleTag[1].trim();
  }
  if (!title) continue;

  // Extract publish date
  let publishDate = null;
  let dateSource = null;

  // Try JSON-LD
  const jsonLd = html.match(/"datePublished"\s*:\s*"([^"]+)"/i);
  if (jsonLd) {
    publishDate = jsonLd[1];
    dateSource = 'jsonld';
  }

  // Try OpenGraph
  if (!publishDate) {
    const ogDate = html.match(/property=["']article:published_time["'][^>]*content=["']([^"']+)["']/i) ||
                   html.match(/content=["']([^"']+)["'][^>]*property=["']article:published_time["']/i);
    if (ogDate) {
      publishDate = ogDate[1];
      dateSource = 'opengraph';
    }
  }

  // Try time element
  if (!publishDate) {
    const timeEl = html.match(/<time[^>]*datetime=["']([^"']+)["']/i);
    if (timeEl) {
      publishDate = timeEl[1];
      dateSource = 'time';
    }
  }

  // Skip if no date found
  if (!publishDate) continue;

  // Validate date is recent (within 7 days)
  try {
    const pubDate = new Date(publishDate);
    const now = new Date();
    const daysDiff = (now - pubDate) / (1000 * 60 * 60 * 24);
    if (daysDiff < 0 || daysDiff > 7) continue;
  } catch (e) { continue; }

  // Extract paragraphs for content
  const paragraphs = [];
  const pRegex = /<p[^>]*>([^<]{50,})<\/p>/gi;
  let pMatch;
  while ((pMatch = pRegex.exec(html)) !== null && paragraphs.length < 10) {
    const text = pMatch[1].replace(/<[^>]*>/g, '').trim();
    if (text.length > 50) paragraphs.push(text);
  }
  const content = paragraphs.join(' ').substring(0, 2000);
  if (content.length < 200) continue;

  // Extract source name
  let sourceName = '';
  const ogSite = html.match(/property=["']og:site_name["'][^>]*content=["']([^"']+)["']/i);
  if (ogSite) sourceName = ogSite[1];
  if (!sourceName) {
    try { sourceName = new URL(articleUrl).hostname.replace('www.', ''); } catch(e) {}
  }

  articles.push({
    json: {
      url: articleUrl,
      title: title.substring(0, 200),
      content: content,
      publish_date: publishDate,
      date_source: dateSource,
      source_name: sourceName,
      genre: genre,
      client_id: clientId,
      run_id: runId,
      recipients: recipients
    }
  });
}

if (articles.length === 0) {
  return [{ json: { no_articles: true, reason: 'No valid articles extracted' } }];
}

return articles.slice(0, 10); // Max 10 articles

// Combine AI response with article data
const items = $input.all();
const processed = [];

for (const item of items) {
  const original = item.json;

  let aiData = { headline: '', summary: '', why_matters: '' };
  try {
    const content = original.message?.content || original.text || '{}';
    aiData = JSON.parse(content);
  } catch (e) {
    aiData = {
      headline: original.title || 'Untitled',
      summary: original.content?.substring(0, 200) || 'No summary available.',
      why_matters: 'Relevant to the industry.'
    };
  }

  processed.push({
    json: {
      url: original.url,
      headline: aiData.headline || original.title,
      summary: aiData.summary || 'Summary not available.',
      why_matters: aiData.why_matters || 'Industry relevance.',
      source_name: original.source_name,
      publish_date: original.publish_date,
      genre: original.genre,
      client_id: original.client_id,
      run_id: original.run_id,
      recipients: original.recipients
    }
  });
}

return processed;

// Build email HTML
const articles = $input.all().map(i => i.json);

const genreColors = {
  'Office Equipment & Technology': '#2563eb',
  'Food & Drink': '#dc2626',
  'Telecommunications & Internet': '#7c3aed',
  'Healthcare': '#059669',
  'Education': '#0891b2',
  'Charity & Nonprofit': '#db2777',
  'Fashion': '#c026d3',
  'Retail': '#ea580c',
  'Professional & Business Services': '#4f46e5',
  'Property & Construction': '#ca8a04',
  'Agencies': '#0d9488',
  'Entertainment': '#e11d48',
  'Transportation & Logistics': '#1d4ed8',
  'Consumer Electronics': '#6366f1',
  'Travel & Tourism': '#0284c7',
  'Financial': '#15803d',
  'Utilities & Energy': '#a16207',
  'Leisure & Hospitality': '#be185d',
  'Media & Publishing': '#9333ea',
  'Government & Public Sector': '#1e40af',
  'Cosmetics & Personal Care': '#ec4899',
  'Home & Garden': '#65a30d',
  'Automotive': '#b91c1c',
  'Manufacturing & Industrial': '#475569',
  'Household Consumer Goods': '#d97706'
};

const today = new Date().toLocaleDateString('en-GB', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'Europe/London'
});

let recipients = [];
if (articles.length > 0 && articles[0].recipients) {
  recipients = articles[0].recipients;
}

// Group by genre
const byGenre = {};
for (const a of articles) {
  if (!byGenre[a.genre]) byGenre[a.genre] = [];
  byGenre[a.genre].push(a);
}

// Build HTML
let html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>44 News</title></head><body style="font-family: -apple-system, BlinkMacSystemFont, sans-serif; background: #f3feff; margin: 0; padding: 20px;"><div style="max-width: 600px; margin: 0 auto;"><div style="background: linear-gradient(135deg, #003d96, #0056b3); color: white; padding: 30px; text-align: center; border-radius: 12px 12px 0 0;"><h1 style="margin: 0;">44 News Automation</h1><p style="margin: 10px 0 0; opacity: 0.9;">Morning Brief — ${today}</p></div><div style="background: white; padding: 30px; border-radius: 0 0 12px 12px;">`;

if (articles.length === 0) {
  html += `<p style="text-align: center; color: #666;">No qualifying stories found today. We'll be back tomorrow.</p>`;
} else {
  for (const genre of Object.keys(byGenre).sort()) {
    const color = genreColors[genre] || '#003d96';
    html += `<div style="background: ${color}; color: white; padding: 12px 20px; border-radius: 8px; margin: 20px 0 15px; font-weight: 600;">${genre}</div>`;

    for (const article of byGenre[genre]) {
      html += `<div style="background: #f8fafc; padding: 20px; border-radius: 8px; margin-bottom: 15px; border-left: 4px solid ${color};">`;
      html += `<h3 style="margin: 0 0 10px; font-size: 17px;"><a href="${article.url}" style="color: #003d96; text-decoration: none;">${article.headline}</a></h3>`;
      html += `<p style="font-size: 12px; color: #666; margin: 0 0 10px;">${article.source_name}</p>`;
      html += `<p style="font-size: 14px; color: #333; margin: 0 0 12px;">${article.summary}</p>`;
      html += `<div style="background: #e0f2fe; padding: 12px; border-radius: 6px; border-left: 3px solid #0284c7;"><strong style="color: #0369a1;">Why this matters:</strong> <span style="color: #475569; font-size: 13px;">${article.why_matters}</span></div>`;
      html += `</div>`;
    }
  }
}

html += `</div><p style="text-align: center; color: #666; font-size: 12px; margin-top: 20px;">Automated by 44 News Automation</p></div></body></html>`;

return [{
  json: {
    emailHtml: html,
    emailSubject: `44 News Automation — Morning Brief — ${today}`,
    recipients: recipients,
    storyCount: articles.length,
    client_id: articles[0]?.client_id,
    run_id: articles[0]?.run_id
  }
}];
